package com.primehr.migration;import org.junit.jupiter.api.Test;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Set;import static org.assertj.core.api.Assertions.assertThat;
class EvidenceV53MigrationParityTest{@Test void pairedMigrationsHaveMatchingProviderNeutralStructures()throws Exception{String p=read("db/migration/postgresql/V53__evidence_framework_foundation.sql").toLowerCase(),s=read("db/migration/sqlserver/V53__evidence_framework_foundation.sql").toLowerCase();Set<String>names=Set.of("evidence_framework","evidence_framework_version","evidence_pillar","evidence_governance_level","evidence_indicator","evidence_requirement","uk_evidence_framework_code","uk_evidence_framework_version","ix_evidence_framework_effective","ix_evidence_pillar_framework","ix_evidence_level_framework","ix_evidence_indicator_pillar","ix_evidence_requirement_indicator");for(String migration:Set.of(p,s)){assertThat(migration).contains(names.toArray(String[]::new));assertThat(migration).doesNotContain("insert into","delete from","drop table","employeeappointment","payroll_transaction");}}private String read(String path)throws IOException{try(var in=getClass().getClassLoader().getResourceAsStream(path)){if(in==null)throw new IOException(path);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}}
